/* NexusCRM v4 — app.js — Universal All-in-One CRM */
const TOKEN=localStorage.getItem('nexus_token');
const CUSER=JSON.parse(localStorage.getItem('nexus_user')||'{}');
const TENANT=JSON.parse(localStorage.getItem('nexus_tenant')||'{}');
if(!TOKEN)window.location.href='/login.html';
const H=()=>({'Content-Type':'application/json','Authorization':`Bearer ${TOKEN}`});
async function api(path,opts={}){try{const res=await fetch(path,{headers:H(),...opts});if(res.status===401||res.status===403){logout();return null;}return res;}catch{toast('Server unreachable','error');return null;}}

// State
let contacts=[],invoices=[],messages=[],templates=[],reminders=[],proposals=[];
let projects=[],tickets=[],contracts=[],expenses=[],campaigns=[],flows=[];
let dragId=null,activeMsgCid=null,activeChannel='whatsapp',editingId=null,isAdding=false;
let invItems=[],propItems=[],aiHistory=[];

// Helpers
const PALS=[{bg:'rgba(59,130,246,.2)',c:'#60a5fa'},{bg:'rgba(34,197,94,.18)',c:'#4ade80'},{bg:'rgba(245,158,11,.18)',c:'#fbbf24'},{bg:'rgba(168,85,247,.18)',c:'#c084fc'},{bg:'rgba(20,184,166,.18)',c:'#2dd4bf'},{bg:'rgba(249,115,22,.18)',c:'#fb923c'}];
const pal=n=>{let h=0;for(const c of(n||''))h=(h*31+c.charCodeAt(0))&0xffff;return PALS[h%PALS.length]};
const init=n=>(n||'?').split(' ').map(p=>p[0]).join('').slice(0,2).toUpperCase();
const setAv=(el,n)=>{const p=pal(n);el.style.background=p.bg;el.style.color=p.c;el.textContent=init(n)};
const $m=v=>v!=null?'$'+Number(v).toLocaleString('en-US',{minimumFractionDigits:0,maximumFractionDigits:0}):'—';
const $d=d=>d?new Date(d).toLocaleDateString('en-GB',{day:'numeric',month:'short',year:'numeric'}):'—';
const $ago=d=>{if(!d)return'—';const s=Math.floor((Date.now()-new Date(d))/1000);if(s<60)return'just now';if(s<3600)return`${Math.floor(s/60)}m ago`;if(s<86400)return`${Math.floor(s/3600)}h ago`;return`${Math.floor(s/86400)}d ago`};
const scoreColor=s=>s>=70?'var(--accent-green)':s>=40?'var(--accent-amber)':'var(--accent-red)';

function toast(msg,type='success'){const d=document.createElement('div');d.className=`toast ${type}`;d.innerHTML=`<span class="toast-dot"></span>${msg}`;document.getElementById('toastContainer').appendChild(d);setTimeout(()=>d.remove(),3500)}

// Clock
setInterval(()=>{const el=document.getElementById('topbarTime');if(el)el.textContent=new Date().toLocaleTimeString('en-GB',{hour:'2-digit',minute:'2-digit',second:'2-digit'})},1000);

// Theme
let dark=true;
document.getElementById('themeToggle')?.addEventListener('click',()=>{dark=!dark;document.body.classList.toggle('light',!dark)});

// Sidebar
function initSidebar(){
  const name=CUSER.name||'User',role=CUSER.role||'user',plan=TENANT.plan||'starter';
  document.getElementById('sidebarName').textContent=name;
  document.getElementById('sidebarRole').textContent=role.charAt(0).toUpperCase()+role.slice(1);
  setAv(document.getElementById('sidebarAvatar'),name);
  const chip=document.getElementById('planChip');chip.textContent=plan;chip.className=`plan-chip ${plan}`;
  if(role==='admin')document.querySelectorAll('.admin-only').forEach(el=>el.style.display='flex');
}

function logout(){localStorage.clear();window.location.href='/login.html'}
document.getElementById('logoutBtn')?.addEventListener('click',logout);
document.getElementById('menuToggle')?.addEventListener('click',()=>document.getElementById('sidebar').classList.toggle('open'));

// Navigation
const TITLES={dashboard:'Dashboard',ai:'AI Assistant',contacts:'Contacts',pipeline:'Pipeline',messaging:'Messaging',proposals:'Proposals',invoices:'Invoices',contracts:'Contracts',projects:'Projects',helpdesk:'Help Desk',finance:'Finance',campaigns:'Campaigns',automation:'Automation',templates:'Templates',reminders:'Reminders',analytics:'Analytics',team:'Team',billing:'Billing',admin:'Admin'};
document.querySelectorAll('[data-page]').forEach(el=>{el.addEventListener('click',e=>{e.preventDefault();navigateTo(el.dataset.page);document.getElementById('sidebar').classList.remove('open')})});

function navigateTo(page){
  document.querySelectorAll('.page').forEach(p=>p.classList.remove('active'));
  document.querySelectorAll('.nav-item').forEach(n=>n.classList.remove('active'));
  document.getElementById(`page-${page}`)?.classList.add('active');
  document.querySelectorAll(`[data-page="${page}"]`).forEach(el=>el.classList.add('active'));
  document.getElementById('pageTitle').textContent=TITLES[page]||page;
  const renders={dashboard:renderDashboard,ai:renderAI,contacts:renderContacts,pipeline:renderPipeline,messaging:renderMessaging,proposals:renderProposals,invoices:renderInvoices,contracts:renderContracts,projects:renderProjects,helpdesk:renderHelpDesk,finance:renderFinance,campaigns:renderCampaigns,automation:renderAutomation,templates:renderTemplates,reminders:renderReminders,analytics:renderAnalytics,team:renderTeam,billing:renderBilling,admin:renderAdmin};
  if(renders[page])renders[page]();
}

// Load all
async function loadAll(){
  const rs=await Promise.all([api('/api/contacts'),api('/api/invoices'),api('/api/messages'),api('/api/templates'),api('/api/reminders'),api('/api/proposals'),api('/api/projects'),api('/api/tickets'),api('/api/contracts'),api('/api/expenses'),api('/api/campaigns'),api('/api/automation')]);
  if(rs[0])contacts=await rs[0].json();
  if(rs[1])invoices=await rs[1].json();
  if(rs[2])messages=await rs[2].json();
  if(rs[3])templates=await rs[3].json();
  if(rs[4])reminders=await rs[4].json();
  if(rs[5])proposals=await rs[5].json();
  if(rs[6])projects=await rs[6].json();
  if(rs[7])tickets=await rs[7].json();
  if(rs[8])contracts=await rs[8].json();
  if(rs[9])expenses=await rs[9].json();
  if(rs[10])campaigns=await rs[10].json();
  if(rs[11])flows=await rs[11].json();
  document.getElementById('navContactCount').textContent=contacts.length;
  const pendR=reminders.filter(r=>r.status==='pending'&&new Date(r.due_at)<=new Date(Date.now()+86400000)).length;
  if(document.getElementById('navRemCount'))document.getElementById('navRemCount').textContent=pendR||'';
  if(document.getElementById('navTicketCount'))document.getElementById('navTicketCount').textContent=tickets.filter(t=>t.status==='open').length||'';
  if(document.getElementById('navPropCount'))document.getElementById('navPropCount').textContent=proposals.filter(p=>p.status==='sent').length||'';
}

// DASHBOARD
async function renderDashboard(){
  const res=await api('/api/stats');if(!res)return;
  const d=await res.json();
  const hr=new Date().getHours();
  document.getElementById('dashGreeting').textContent=`${hr<12?'Good morning':hr<17?'Good afternoon':'Good evening'}, ${CUSER.name?.split(' ')[0]||''}`;
  animCount('kpiContacts',d.total_contacts);
  document.getElementById('kpiRevenue').textContent=$m(d.revenue);
  document.getElementById('kpiPipeline').textContent=$m(d.pipeline);
  animCount('kpiTickets',d.open_tickets||0);
  animCount('kpiProjects',d.active_projects||0);
  animCount('kpiContracts',d.active_contracts||0);
  document.getElementById('kpiExpenses').textContent=$m(d.total_expenses||0);
  animCount('kpiReminders',d.pending_reminders||0);
  document.getElementById('kpiLeadsDelta').textContent=`${d.leads} leads · ${d.clients} clients`;
  document.getElementById('recentContacts').innerHTML=contacts.slice(0,5).map(c=>{const p=pal(c.name);return`<div class="recent-item" onclick="openView(${c.id})"><div class="r-avatar" style="background:${p.bg};color:${p.c}">${init(c.name)}</div><div><div class="r-name">${c.name}</div><div class="r-meta">${c.company||'—'}</div></div><span class="status-badge badge-${c.status}">${c.status}</span></div>`}).join('')||'<div style="padding:20px;color:var(--text-muted);font-size:13px">No contacts yet</div>';
  const total=contacts.length||1;
  document.getElementById('statusChart').innerHTML=['Lead','Client','Partner','Churned'].map(s=>{const cols={Lead:'var(--accent-amber)',Client:'var(--accent-green)',Partner:'var(--accent-blue)',Churned:'var(--accent-red)'};const n=contacts.filter(c=>c.status===s).length;return`<div class="status-row"><div class="sr-header"><span class="sr-label">${s}</span><span class="sr-count">${n}</span></div><div class="bar-track"><div class="bar-fill" style="width:${Math.round(n/total*100)}%;background:${cols[s]}"></div></div></div>`}).join('');
  document.getElementById('activityFeed').innerHTML=(d.recent_activity||[]).slice(0,10).map(a=>`<div class="activity-item"><div class="ai-dot"></div><div class="ai-text"><b>${a.user_name||'System'}</b> ${a.action.replace(/_/g,' ')}${a.contact_name?` · ${a.contact_name}`:''}</div><div class="ai-time">${$ago(a.created_at)}</div></div>`).join('')||'<div style="padding:20px;color:var(--text-muted);font-size:13px">No activity yet</div>';
  const br=await api('/api/ai/briefing');if(!br)return;
  const bd=await br.json();
  const briefEl=document.getElementById('aiBriefing');
  if(briefEl)briefEl.innerHTML=bd.high_priority?.length?bd.high_priority.map(s=>{const p=pal(s.name);return`<div class="recent-item" onclick="navigateTo('contacts')" style="cursor:pointer"><div class="r-avatar" style="background:${p.bg};color:${p.c}">${init(s.name)}</div><div style="flex:1"><div class="r-name">${s.name} <span style="font-size:11px;font-weight:400;color:var(--text-secondary)">· Score: <span style="color:${scoreColor(s.score)}">${s.score}%</span></span></div><div class="r-meta">${s.reason}</div></div><div style="font-size:11px;color:var(--accent-amber);flex-shrink:0">${s.action}</div></div>`}).join(''):'<div style="padding:14px 18px;font-size:13px;color:var(--text-muted)">✅ All contacts are up to date.</div>';
}

function animCount(id,target){const el=document.getElementById(id);if(!el)return;let cur=0;const step=Math.max(1,Math.ceil(target/30));const t=setInterval(()=>{cur=Math.min(cur+step,target);el.textContent=cur;if(cur>=target)clearInterval(t)},25)}

// AI ASSISTANT
function renderAI(){}

document.getElementById('aiSend')?.addEventListener('click',sendAIMessage);
document.getElementById('aiInput')?.addEventListener('keydown',e=>{if(e.key==='Enter'&&!e.shiftKey){e.preventDefault();sendAIMessage()}});
document.getElementById('clearAiBtn')?.addEventListener('click',async()=>{await api('/api/ai/chat',{method:'DELETE'});aiHistory=[];document.getElementById('aiThread').innerHTML='<div class="ai-msg assistant"><div class="ai-msg-av">🤖</div><div class="ai-msg-content">Chat cleared! How can I help you?</div></div>';});

async function sendAIMessage(){
  const input=document.getElementById('aiInput');
  const text=input?.value?.trim();if(!text)return;
  input.value='';
  const thread=document.getElementById('aiThread');
  thread.innerHTML+=`<div class="ai-msg user"><div class="ai-msg-av">👤</div><div class="ai-msg-content">${text}</div></div>`;
  const typing=document.createElement('div');typing.className='ai-msg assistant';typing.innerHTML='<div class="ai-msg-av">🤖</div><div class="ai-typing"><span></span><span></span><span></span></div>';
  thread.appendChild(typing);thread.scrollTop=thread.scrollHeight;
  const res=await api('/api/ai/chat',{method:'POST',body:JSON.stringify({message:text})});
  typing.remove();
  if(res){const d=await res.json();thread.innerHTML+=`<div class="ai-msg assistant"><div class="ai-msg-av">🤖</div><div class="ai-msg-content">${(d.reply||'').replace(/\n/g,'<br>')}</div></div>`;}
  thread.scrollTop=thread.scrollHeight;
}

// CONTACTS
function renderContacts(){
  const q=(document.getElementById('searchInput')?.value||'').toLowerCase();
  const st=document.getElementById('filterStatus')?.value||'';
  const filtered=contacts.filter(c=>{const mq=!q||c.name.toLowerCase().includes(q)||(c.email||'').toLowerCase().includes(q)||(c.company||'').toLowerCase().includes(q);return mq&&(!st||c.status===st)});
  const body=document.getElementById('tableBody');
  document.getElementById('emptyState').style.display=filtered.length?'none':'block';
  body.innerHTML='';
  filtered.forEach(c=>{const p=pal(c.name);const score=c.deal_score??0;const tr=document.createElement('tr');
    tr.innerHTML=`<td onclick="openView(${c.id})"><div class="contact-cell"><div class="t-avatar" style="background:${p.bg};color:${p.c}">${init(c.name)}</div><div><div class="t-name">${c.name}</div><div class="t-email">${c.email||'—'}</div></div></div></td><td onclick="openView(${c.id})"><div style="font-weight:500">${c.company||'—'}</div><div style="font-size:11px;color:var(--text-secondary)">${c.title||'—'}</div></td><td onclick="openView(${c.id})"><span class="status-badge badge-${c.status}">${c.status}</span></td><td onclick="openView(${c.id})" style="font-weight:500">${$m(c.deal)}</td><td onclick="openView(${c.id})"><div style="display:flex;align-items:center;gap:5px"><div style="flex:1;height:4px;background:var(--bg-elevated);border-radius:99px;overflow:hidden"><div style="width:${score}%;height:100%;background:${scoreColor(score)};border-radius:99px"></div></div><span style="font-size:11px;color:${scoreColor(score)};font-weight:500;width:28px;text-align:right">${score}%</span></div></td><td><div class="actions-cell"><button class="icon-btn" title="WhatsApp" onclick="quickWA(${c.id})" style="color:#25d366"><svg viewBox="0 0 20 20" fill="currentColor" width="11" height="11"><path d="M17.472 14.382c-.297-.149-1.758-.867-2.03-.967-.273-.099-.471-.148-.67.15-.197.297-.767.966-.94 1.164-.173.199-.347.223-.644.075-.297-.15-1.255-.463-2.39-1.475-.883-.788-1.48-1.761-1.653-2.059-.173-.297-.018-.458.13-.606.134-.133.298-.347.446-.52.149-.174.198-.298.298-.497.099-.198.05-.371-.025-.52-.075-.149-.669-1.612-.916-2.207-.242-.579-.487-.5-.669-.51-.173-.008-.371-.01-.57-.01-.198 0-.52.074-.792.372-.272.297-1.04 1.016-1.04 2.479 0 1.462 1.065 2.875 1.213 3.074.149.198 2.096 3.2 5.077 4.487.709.306 1.262.489 1.694.625.712.227 1.36.195 1.871.118.571-.085 1.758-.719 2.006-1.413.248-.694.248-1.289.173-1.413-.074-.124-.272-.198-.57-.347zM10 0C4.477 0 0 4.477 0 10c0 1.89.525 3.656 1.438 5.168L0 20l4.948-1.42A9.956 9.956 0 0010 20c5.523 0 10-4.477 10-10S15.523 0 10 0z"/></svg></button><button class="icon-btn" title="Edit" onclick="openEdit(${c.id})"><svg viewBox="0 0 16 16" fill="none" stroke="currentColor" stroke-width="1.5"><path d="M11 2l3 3-8 8H3v-3l8-8z"/></svg></button><button class="icon-btn del" title="Delete" onclick="handleDelete(${c.id})"><svg viewBox="0 0 16 16" fill="none" stroke="currentColor" stroke-width="1.5"><path d="M2 4h12M5 4V2h6v2M6 7v5M10 7v5M3 4l1 10h8l1-10"/></svg></button></div></td>`;
    body.appendChild(tr);});
}
document.getElementById('searchInput')?.addEventListener('input',renderContacts);
document.getElementById('filterStatus')?.addEventListener('change',renderContacts);
document.getElementById('addContactBtn')?.addEventListener('click',openAdd);
document.getElementById('exportBtn')?.addEventListener('click',exportCSV);

// PIPELINE
const STAGES=['Lead','Qualified','Proposal','Closed'];
const SCOLS={Lead:'#f59e0b',Qualified:'#3b82f6',Proposal:'#a855f7',Closed:'#22c55e'};
function renderPipeline(){
  const board=document.getElementById('kanbanBoard');board.innerHTML='';
  STAGES.forEach(stage=>{
    const cards=contacts.filter(c=>(c.stage||c.status)===stage);
    const value=cards.reduce((s,c)=>s+(Number(c.deal)||0),0);
    const col=document.createElement('div');col.className='kanban-col';col.dataset.stage=stage;
    col.innerHTML=`<div class="kanban-col-header"><span class="kanban-dot" style="background:${SCOLS[stage]}"></span><span class="kanban-col-name">${stage}</span><span class="kanban-col-count">${cards.length}</span><span class="kanban-col-value">${$m(value)}</span></div><div class="kanban-cards" id="kcol-${stage}"></div>`;
    board.appendChild(col);
    const zone=col.querySelector('.kanban-cards');
    cards.forEach(c=>{const card=document.createElement('div');card.className='kanban-card';card.draggable=true;card.dataset.id=c.id;const p=pal(c.name);const score=c.deal_score??0;card.innerHTML=`<div style="display:flex;align-items:center;gap:6px;margin-bottom:3px"><div style="width:20px;height:20px;border-radius:50%;background:${p.bg};color:${p.c};font-size:8px;font-weight:600;display:flex;align-items:center;justify-content:center">${init(c.name)}</div><div class="kc-name">${c.name}</div></div><div class="kc-company">${c.company||'—'}</div><div style="display:flex;justify-content:space-between;align-items:center"><div class="kc-value">${$m(c.deal)}</div><div style="font-size:10px;color:${scoreColor(score)}">${score}%</div></div>`;
      card.addEventListener('dragstart',()=>{dragId=c.id;setTimeout(()=>card.classList.add('dragging'),0)});
      card.addEventListener('dragend',()=>{card.classList.remove('dragging');dragId=null});
      card.addEventListener('click',()=>openView(c.id));zone.appendChild(card);});
    zone.addEventListener('dragover',e=>{e.preventDefault();col.classList.add('drag-over')});
    zone.addEventListener('dragleave',()=>col.classList.remove('drag-over'));
    zone.addEventListener('drop',async e=>{e.preventDefault();col.classList.remove('drag-over');if(!dragId)return;const contact=contacts.find(c=>c.id===dragId);if(!contact||(contact.stage||contact.status)===stage)return;const res=await api(`/api/contacts/${dragId}/stage`,{method:'PATCH',body:JSON.stringify({stage})});if(res?.ok){contact.stage=stage;renderPipeline();toast(`Moved ${contact.name} → ${stage}`)}});
  });
}

// MESSAGING
function renderMessaging(){renderMsgList()}
function renderMsgList(filter=''){
  const q=filter.toLowerCase();
  const filtered=contacts.filter(c=>!q||c.name.toLowerCase().includes(q)||(c.company||'').toLowerCase().includes(q));
  document.getElementById('msgContactList').innerHTML=filtered.map(c=>{const p=pal(c.name);const lastMsg=messages.find(m=>m.contact_id===c.id);return`<div class="msg-contact-item ${activeMsgCid===c.id?'active':''}" onclick="openMsgContact(${c.id})"><div class="mci-avatar" style="background:${p.bg};color:${p.c}">${init(c.name)}</div><div style="flex:1;overflow:hidden"><div class="mci-name">${c.name}</div><div class="mci-preview">${lastMsg?lastMsg.content.slice(0,38):c.company||'No messages'}</div></div><div class="mci-time">${lastMsg?$ago(lastMsg.sent_at):''}</div></div>`}).join('');
}
document.getElementById('msgSearch')?.addEventListener('input',e=>renderMsgList(e.target.value));
async function openMsgContact(id){
  activeMsgCid=id;renderMsgList(document.getElementById('msgSearch').value);
  const contact=contacts.find(c=>c.id===id);if(!contact)return;
  document.getElementById('msgEmpty').style.display='none';
  const chat=document.getElementById('msgChat');chat.style.display='flex';
  const p=pal(contact.name);
  document.getElementById('msgHeader').innerHTML=`<div class="msg-h-avatar" style="background:${p.bg};color:${p.c}">${init(contact.name)}</div><div><div class="msg-h-name">${contact.name}</div><div class="msg-h-meta">${contact.company||'—'} · ${contact.phone||'No phone'}</div></div><div class="msg-h-actions"><button class="ch-btn wa-btn ${activeChannel==='whatsapp'?'active':''}" onclick="setChannel('whatsapp')">WhatsApp</button><button class="ch-btn ${activeChannel==='email'?'active':''}" onclick="setChannel('email')">Email</button><button class="ch-btn sms-btn ${activeChannel==='sms'?'active':''}" onclick="setChannel('sms')">SMS</button><button class="ch-btn note-btn ${activeChannel==='note'?'active':''}" onclick="setChannel('note')">Note</button></div>`;
  await loadThread(id);renderCompose(contact);
}
async function loadThread(id){
  const res=await api(`/api/contacts/${id}/messages`);if(!res)return;
  const msgs=await res.json();
  const thread=document.getElementById('msgThread');
  thread.innerHTML=msgs.map(m=>{const out=m.direction==='outbound';return`<div class="msg-bubble ${out?'out':'in'}"><div class="bubble-inner">${m.content}</div><div class="bubble-meta"><span class="ch-pip ${m.channel}">${m.channel}</span>${$ago(m.sent_at)}</div></div>`}).join('')||'<div style="padding:24px;color:var(--text-muted);font-size:13px;text-align:center">No messages yet</div>';
  thread.scrollTop=thread.scrollHeight;
}
function setChannel(ch){activeChannel=ch;if(activeMsgCid)openMsgContact(activeMsgCid)}
function renderCompose(contact){
  const isEmail=activeChannel==='email';
  document.getElementById('msgCompose').innerHTML=`${isEmail?`<div style="margin-bottom:6px"><input type="text" id="emailSubject" class="fi" placeholder="Email subject…"/></div>`:''}<div class="compose-row"><select id="templatePicker" class="fi" style="width:auto;padding:7px 9px;font-size:12px" onchange="applyTpl(${contact.id})"><option value="">Template…</option>${templates.filter(t=>t.channel===activeChannel).map(t=>`<option value="${t.id}">${t.name}</option>`).join('')}</select><textarea class="compose-ta" id="composeText" placeholder="${activeMsgCid?getPH():''}" rows="2"></textarea><button class="send-btn" onclick="sendMsg(${contact.id})"><svg viewBox="0 0 20 20" fill="none" stroke="currentColor" stroke-width="1.5"><line x1="3" y1="10" x2="17" y2="10"/><polyline points="12,5 17,10 12,15"/></svg></button></div><div class="compose-hint">${getHint(contact)}</div>`;
  document.getElementById('composeText').addEventListener('keydown',e=>{if(e.key==='Enter'&&!e.shiftKey){e.preventDefault();sendMsg(contact.id)}});
}
function getPH(){return activeChannel==='whatsapp'?'Type a WhatsApp message…':activeChannel==='email'?'Email body…':activeChannel==='sms'?'SMS…':'Add a note…'}
function getHint(c){if(activeChannel==='whatsapp')return c.whatsapp||c.phone?`Opens WhatsApp to <b>${c.whatsapp||c.phone}</b>`:'⚠ No WhatsApp number';if(activeChannel==='email')return c.email?`To: <b>${c.email}</b>`:'⚠ No email';if(activeChannel==='sms')return c.phone?`SMS to <b>${c.phone}</b>`:'⚠ No phone';return'Note saved to contact log'}
async function applyTpl(cid){const tid=parseInt(document.getElementById('templatePicker').value);if(!tid)return;const res=await api(`/api/templates/${tid}/preview`,{method:'POST',body:JSON.stringify({contact_id:cid})});if(!res)return;const d=await res.json();document.getElementById('composeText').value=d.body;const sub=document.getElementById('emailSubject');if(sub&&d.subject)sub.value=d.subject;}
async function sendMsg(contactId){
  const text=document.getElementById('composeText')?.value?.trim();if(!text)return;
  const contact=contacts.find(c=>c.id===contactId);if(!contact)return;
  if(activeChannel==='whatsapp'){const res=await api(`/api/contacts/${contactId}/whatsapp`,{method:'POST',body:JSON.stringify({message:text})});if(!res)return;const data=await res.json();if(data.waUrl){window.open(data.waUrl,'_blank');toast('WhatsApp opened · logged')}else toast(data.warning||data.error,'warn');}
  else if(activeChannel==='email'){const subject=document.getElementById('emailSubject')?.value?.trim();if(!subject){toast('Subject required','warn');return}const res=await api(`/api/contacts/${contactId}/email`,{method:'POST',body:JSON.stringify({subject,body:text})});if(!res)return;const data=await res.json();toast(data.message||data.warning,data.warning?'warn':'success');}
  else if(activeChannel==='sms'){const res=await api(`/api/contacts/${contactId}/sms`,{method:'POST',body:JSON.stringify({message:text})});if(!res)return;const data=await res.json();toast(data.message||data.warning,data.warning?'warn':'success');}
  else{await api(`/api/contacts/${contactId}/messages`,{method:'POST',body:JSON.stringify({channel:'note',content:text})});toast('Note saved');}
  document.getElementById('composeText').value='';
  await loadThread(contactId);await loadAll();renderMsgList(document.getElementById('msgSearch').value);
}
async function quickWA(id){
  const contact=contacts.find(c=>c.id===id);if(!contact)return;
  openModal(`WhatsApp — ${contact.name}`,`<div class="form-group"><label>Message</label><textarea class="fi ta" id="qaMsg" rows="3" placeholder="Type message…"></textarea></div>`,[{label:'Open WhatsApp',cls:'btn-primary',action:async()=>{const text=document.getElementById('qaMsg').value.trim();if(!text)return;const res=await api(`/api/contacts/${id}/whatsapp`,{method:'POST',body:JSON.stringify({message:text})});const data=await res.json();if(data.waUrl){window.open(data.waUrl,'_blank');toast('WhatsApp opened');closeModal();await loadAll()}else toast(data.warning||data.error,'warn');}}]);
}

