function renderHelpDesk(){
  const q=(document.getElementById('ticketSearch')?.value||'').toLowerCase();
  const st=document.getElementById('ticketFilterStatus')?.value||'';
  const pri=document.getElementById('ticketFilterPriority')?.value||'';
  const filtered=tickets.filter(t=>{const mq=!q||(t.ticket_number||'').toLowerCase().includes(q)||(t.subject||'').toLowerCase().includes(q);return mq&&(!st||t.status===st)&&(!pri||t.priority===pri)});
  document.getElementById('ticketBody').innerHTML=filtered.map(t=>`<tr><td style="font-weight:500">${t.ticket_number}</td><td>${t.subject}</td><td>${t.contact_name||'—'}</td><td><span class="status-badge priority-${t.priority}">${t.priority}</span></td><td><span class="status-badge tkt-${t.status}">${t.status.replace('_',' ')}</span></td><td style="color:var(--text-secondary)">${$ago(t.created_at)}</td><td><div class="actions-cell">${t.status!=='resolved'?`<button class="icon-btn" title="Resolve" onclick="resolveTicket(${t.id})"><svg viewBox="0 0 16 16" fill="none" stroke="currentColor" stroke-width="1.5"><polyline points="2,8 6,12 14,4"/></svg></button>`:''}<button class="icon-btn" title="View" onclick="viewTicket(${t.id})"><svg viewBox="0 0 16 16" fill="none" stroke="currentColor" stroke-width="1.5"><path d="M1 8s2.5-5 7-5 7 5 7 5-2.5 5-7 5-7-5-7-5z"/><circle cx="8" cy="8" r="2"/></svg></button></div></td></tr>`).join('')||'<tr><td colspan="7" style="padding:40px;text-align:center;color:var(--text-muted)">No tickets</td></tr>';
}
