document.getElementById('addTicketBtn')?.addEventListener('click',()=>{const cOpts=contacts.map(c=>`<option value="${c.id}">${c.name} — ${c.company||'—'}</option>`).join('');openModal('New Ticket',`<div class="form-group"><label>Contact</label><select class="fi" id="tkt-contact"><option value="">Select…</option>${cOpts}</select></div><div class="form-group"><label>Subject</label><input class="fi" id="tkt-subject" placeholder="Describe the issue…"/></div><div class="form-group"><label>Body</label><textarea class="fi ta" id="tkt-body" rows="3" placeholder="Full description…"></textarea></div><div class="form-group"><label>Priority</label><select class="fi" id="tkt-priority"><option value="high">High</option><option value="medium" selected>Medium</option><option value="low">Low</option></select></div>`,[{label:'Create Ticket',cls:'btn-primary',action:async()=>{const data={contact_id:parseInt(document.getElementById('tkt-contact').value)||null,subject:document.getElementById('tkt-subject').value.trim(),body:document.getElementById('tkt-body').value.trim(),priority:document.getElementById('tkt-priority').value};if(!data.subject||!data.body){toast('Subject and body required','warn');return}await api('/api/tickets',{method:'POST',body:JSON.stringify(data)});toast('Ticket created!');closeModal();const tr=await api('/api/tickets');if(tr)tickets=await tr.json();renderHelpDesk();}}]);});
async function resolveTicket(id){await api(`/api/tickets/${id}`,{method:'PATCH',body:JSON.stringify({status:'resolved'})});toast('Ticket resolved ✅');const tr=await api('/api/tickets');if(tr)tickets=await tr.json();renderHelpDesk();}
async function viewTicket(id){const res=await api(`/api/tickets/${id}`);if(!res)return;const t=await res.json();openModal(`${t.ticket_number} — ${t.subject}`,`<p style="font-size:13px;color:var(--text-secondary);margin-bottom:12px">${t.body}</p><div style="border-top:1px solid var(--border);padding-top:10px"><div style="font-size:11px;text-transform:uppercase;letter-spacing:.07em;color:var(--text-muted);margin-bottom:8px">Replies</div>${(t.messages||[]).map(m=>`<div style="padding:7px;background:var(--bg-elevated);border-radius:7px;margin-bottom:5px;font-size:13px">${m.content}</div>`).join('')||'<p style="font-size:13px;color:var(--text-muted)">No replies yet</p>'}<textarea class="fi ta" id="reply-text" rows="2" style="margin-top:8px" placeholder="Add a reply…"></textarea></div>`,[{label:'Send Reply',cls:'btn-primary',action:async()=>{const content=document.getElementById('reply-text').value.trim();if(!content)return;await api(`/api/tickets/${id}/messages`,{method:'POST',body:JSON.stringify({content})});toast('Reply sent');closeModal();}}]);}

// FINANCE
async function renderFinance(){
  const res=await api('/api/finance/summary');if(!res)return;const d=await res.json();
  document.getElementById('financeCards').innerHTML=`<div class="finance-card"><div class="fc-label">Total Revenue</div><div class="fc-value" style="color:var(--accent-green)">${$m(d.revenue)}</div><div class="fc-sub">From paid invoices</div></div><div class="finance-card"><div class="fc-label">Total Expenses</div><div class="fc-value" style="color:var(--accent-red)">${$m(d.expenses)}</div><div class="fc-sub">Approved expenses</div></div><div class="finance-card"><div class="fc-label">Net Profit</div><div class="fc-value" style="color:${d.profit>=0?'var(--accent-green)':'var(--accent-red)'}">${$m(d.profit)}</div><div class="fc-sub">Revenue minus expenses</div></div><div class="finance-card"><div class="fc-label">Pending Invoices</div><div class="fc-value" style="color:var(--accent-amber)">${$m(d.invoices_pending)}</div><div class="fc-sub">Awaiting payment</div></div>`;
  document.getElementById('expenseBody').innerHTML=expenses.map(e=>`<tr><td>${e.description}</td><td>${e.category}</td><td style="font-weight:500">${$m(e.amount)}</td><td style="color:var(--text-secondary)">${$d(e.date)}</td><td><span class="status-badge ${e.status==='approved'?'badge-Client':e.status==='pending'?'badge-Lead':'badge-Churned'}">${e.status}</span></td><td><div class="actions-cell">${e.status==='pending'&&CUSER.role==='admin'?`<button class="icon-btn" title="Approve" onclick="approveExpense(${e.id})"><svg viewBox="0 0 16 16" fill="none" stroke="currentColor" stroke-width="1.5"><polyline points="2,8 6,12 14,4"/></svg></button>`:''}<button class="icon-btn del" onclick="deleteExpense(${e.id})"><svg viewBox="0 0 16 16" fill="none" stroke="currentColor" stroke-width="1.5"><path d="M2 4h12M5 4V2h6v2M6 7v5M10 7v5M3 4l1 10h8l1-10"/></svg></button></div></td></tr>`).join('')||'<tr><td colspan="6" style="padding:40px;text-align:center;color:var(--text-muted)">No expenses</td></tr>';
}
document.getElementById('addExpenseBtn')?.addEventListener('click',()=>{openModal('Log Expense',`<div class="form-group"><label>Description</label><input class="fi" id="exp-desc" placeholder="What was this for?"/></div><div class="form-group"><label>Category</label><select class="fi" id="exp-cat"><option>Travel</option><option>Software</option><option>Marketing</option><option>Office</option><option>Meals</option><option>Equipment</option></select></div><div class="form-group"><label>Amount ($)</label><input type="number" class="fi" id="exp-amount" value="0"/></div><div class="form-group"><label>Date</label><input type="date" class="fi" id="exp-date"/></div>`,[{label:'Log Expense',cls:'btn-primary',action:async()=>{const data={description:document.getElementById('exp-desc').value.trim(),category:document.getElementById('exp-cat').value,amount:parseFloat(document.getElementById('exp-amount').value)||0,date:document.getElementById('exp-date').value,status:'pending'};if(!data.description){toast('Description required','warn');return}await api('/api/expenses',{method:'POST',body:JSON.stringify(data)});toast('Expense logged!');closeModal();const er=await api('/api/expenses');if(er)expenses=await er.json();renderFinance();}}]);});
async function approveExpense(id){await api(`/api/expenses/${id}/status`,{method:'PATCH',body:JSON.stringify({status:'approved'})});toast('Approved');const er=await api('/api/expenses');if(er)expenses=await er.json();renderFinance();}
async function deleteExpense(id){if(!confirm('Delete expense?'))return;await api(`/api/expenses/${id}`,{method:'DELETE'});toast('Deleted');const er=await api('/api/expenses');if(er)expenses=await er.json();renderFinance();}

// CAMPAIGNS
function renderCampaigns(){
  document.getElementById('campaignsList').innerHTML=campaigns.map(c=>`<div class="dash-panel" style="margin-bottom:10px"><div class="panel-header"><span class="panel-title">${c.name}</span><span class="status-badge ${c.status==='sent'?'badge-Client':'badge-Lead'}">${c.status}</span></div><div style="padding:14px 16px"><div style="font-size:13px;color:var(--text-secondary);margin-bottom:10px">Subject: ${c.subject||'—'} · Segment: ${c.segment||'all'}</div><div style="display:flex;gap:18px"><div><div style="font-family:var(--font-serif);font-size:22px">${c.opens||0}</div><div style="font-size:11px;color:var(--text-muted);text-transform:uppercase;letter-spacing:.07em">Opens</div></div><div><div style="font-family:var(--font-serif);font-size:22px">${c.clicks||0}</div><div style="font-size:11px;color:var(--text-muted);text-transform:uppercase;letter-spacing:.07em">Clicks</div></div><div style="margin-left:auto;display:flex;gap:6px;align-items:center">${c.status==='draft'?`<button class="btn-primary" style="font-size:12px;padding:6px 12px" onclick="sendCampaign(${c.id})">Send Campaign</button>`:''}<button class="btn-ghost" style="font-size:12px;padding:6px 10px" onclick="deleteCampaign(${c.id})">Delete</button></div></div></div></div>`).join('')||'<div style="padding:30px;color:var(--text-muted);font-size:13px">No campaigns yet</div>';
}
document.getElementById('addCampaignBtn')?.addEventListener('click',()=>{openModal('New Campaign',`<div class="form-group"><label>Campaign Name</label><input class="fi" id="camp-name" placeholder="e.g. May Newsletter"/></div><div class="form-group"><label>Subject</label><input class="fi" id="camp-subject" placeholder="Email subject line"/></div><div class="form-group"><label>Segment</label><select class="fi" id="camp-segment"><option value="all">All contacts</option><option value="leads">Leads only</option><option value="clients">Clients only</option><option value="partners">Partners only</option></select></div><div class="form-group"><label>Body (HTML or plain text)</label><textarea class="fi ta" id="camp-body" rows="5" placeholder="Hi {{name}},\n\nYour email content here…"></textarea></div>`,[{label:'Save Campaign',cls:'btn-primary',action:async()=>{const data={name:document.getElementById('camp-name').value.trim(),subject:document.getElementById('camp-subject').value.trim(),segment:document.getElementById('camp-segment').value,body:document.getElementById('camp-body').value};if(!data.name||!data.subject){toast('Name and subject required','warn');return}await api('/api/campaigns',{method:'POST',body:JSON.stringify(data)});toast('Campaign saved!');closeModal();const cr=await api('/api/campaigns');if(cr)campaigns=await cr.json();renderCampaigns();}}]);});
async function sendCampaign(id){if(!confirm('Send this campaign to all matching contacts?'))return;toast('Sending…','success');const res=await api(`/api/campaigns/${id}/send`,{method:'POST'});if(!res)return;const d=await res.json();toast(d.message||d.warning,d.warning?'warn':'success');const cr=await api('/api/campaigns');if(cr)campaigns=await cr.json();renderCampaigns();}
async function deleteCampaign(id){if(!confirm('Delete campaign?'))return;await api(`/api/campaigns/${id}`,{method:'DELETE'});toast('Deleted');const cr=await api('/api/campaigns');if(cr)campaigns=await cr.json();renderCampaigns();}

// AUTOMATION
function renderAutomation(){
  document.getElementById('flowBody').innerHTML=flows.map(f=>`<tr><td style="font-weight:500">${f.name}</td><td><span class="status-badge badge-Partner">${f.trigger}</span></td><td><span class="status-badge ${f.status==='active'?'badge-Client':'badge-Churned'}">${f.status}</span></td><td>${f.run_count||0} runs</td><td><div class="actions-cell"><button class="icon-btn" onclick="toggleFlow(${f.id},'${f.status}')"><svg viewBox="0 0 16 16" fill="none" stroke="currentColor" stroke-width="1.5"><path d="M5 3l8 5-8 5z"/></svg></button><button class="icon-btn del" onclick="deleteFlow(${f.id})"><svg viewBox="0 0 16 16" fill="none" stroke="currentColor" stroke-width="1.5"><path d="M2 4h12M5 4V2h6v2M6 7v5M10 7v5M3 4l1 10h8l1-10"/></svg></button></div></td></tr>`).join('')||'<tr><td colspan="5" style="padding:40px;text-align:center;color:var(--text-muted)">No automation flows</td></tr>';
}
document.getElementById('addFlowBtn')?.addEventListener('click',()=>{openModal('New Automation Flow',`<div class="form-group"><label>Flow Name</label><input class="fi" id="flow-name" placeholder="e.g. New Lead Welcome"/></div><div class="form-group"><label>Trigger</label><select class="fi" id="flow-trigger"><option value="contact_created">Contact Created</option><option value="no_contact_days">No Contact (days)</option><option value="stage_changed">Stage Changed</option></select></div><div class="form-group"><label>Action</label><select class="fi" id="flow-action"><option value="send_email">Send Email Template</option><option value="set_reminder">Set Follow-up Reminder</option></select></div><div class="form-group"><label>Template Name (for email action)</label><input class="fi" id="flow-template" placeholder="e.g. Introduction"/></div>`,[{label:'Create Flow',cls:'btn-primary',action:async()=>{const data={name:document.getElementById('flow-name').value.trim(),trigger:document.getElementById('flow-trigger').value,conditions:'[]',actions:JSON.stringify([{type:document.getElementById('flow-action').value,template:document.getElementById('flow-template').value}]),status:'active'};if(!data.name){toast('Name required','warn');return}await api('/api/automation',{method:'POST',body:JSON.stringify(data)});toast('Flow created!');closeModal();const fr=await api('/api/automation');if(fr)flows=await fr.json();renderAutomation();}}]);});
async function toggleFlow(id,status){const newStatus=status==='active'?'paused':'active';await api(`/api/automation/${id}`,{method:'PATCH',body:JSON.stringify({status:newStatus})});toast(`Flow ${newStatus}`);const fr=await api('/api/automation');if(fr)flows=await fr.json();renderAutomation();}
async function deleteFlow(id){if(!confirm('Delete flow?'))return;await api(`/api/automation/${id}`,{method:'DELETE'});toast('Deleted');const fr=await api('/api/automation');if(fr)flows=await fr.json();renderAutomation();}

// TEMPLATES
function renderTemplates(){
  const cColors={email:'var(--accent-blue)',whatsapp:'#25d366',sms:'var(--accent-amber)',note:'var(--accent-purple)'};
  document.getElementById('templatesGrid').innerHTML=templates.map(t=>`<div class="tpl-card"><div class="tpl-header"><span class="tpl-channel" style="background:${cColors[t.channel]||'var(--accent-blue)'}22;color:${cColors[t.channel]||'var(--accent-blue)'}">${t.channel}</span><span class="tpl-name">${t.name}</span></div>${t.subject?`<div style="font-size:11px;color:var(--text-secondary);padding:5px 13px 0;font-style:italic">${t.subject}</div>`:''}<div class="tpl-body">${t.body.slice(0,100)}${t.body.length>100?'…':''}</div><div class="tpl-footer"><button class="btn-ghost" style="font-size:12px;padding:5px 9px" onclick="editTemplate(${t.id})">Edit</button><button class="btn-ghost" style="font-size:12px;padding:5px 9px;color:var(--accent-red);border-color:rgba(239,68,68,.3)" onclick="deleteTemplate(${t.id})">Delete</button></div></div>`).join('')||'<div style="color:var(--text-muted);font-size:13px;padding:20px">No templates yet</div>';
}
document.getElementById('addTemplateBtn')?.addEventListener('click',()=>{openModal('New Template',`<div class="form-group"><label>Name</label><input class="fi" id="tpl-name" placeholder="Template name"/></div><div class="form-group"><label>Channel</label><select class="fi" id="tpl-channel"><option value="email">Email</option><option value="whatsapp">WhatsApp</option><option value="sms">SMS</option><option value="note">Note</option></select></div><div class="form-group"><label>Subject (email only)</label><input class="fi" id="tpl-subject" placeholder="Email subject with {{name}}"/></div><div class="form-group"><label>Body — use {{name}}, {{company}}, {{deal}}, {{sender_name}}</label><textarea class="fi ta" id="tpl-body" rows="5" placeholder="Hi {{name}},\n\n…"></textarea></div>`,[{label:'Save',cls:'btn-primary',action:async()=>{const data={name:document.getElementById('tpl-name').value.trim(),channel:document.getElementById('tpl-channel').value,subject:document.getElementById('tpl-subject').value.trim(),body:document.getElementById('tpl-body').value.trim()};if(!data.name||!data.body){toast('Name and body required','warn');return}await api('/api/templates',{method:'POST',body:JSON.stringify(data)});toast('Template saved!');closeModal();const tr=await api('/api/templates');if(tr)templates=await tr.json();renderTemplates();}}]);});
async function editTemplate(id){const t=templates.find(x=>x.id===id);if(!t)return;openModal('Edit Template',`<div class="form-group"><label>Name</label><input class="fi" id="tpl-name" value="${t.name}"/></div><div class="form-group"><label>Channel</label><select class="fi" id="tpl-channel"><option value="email" ${t.channel==='email'?'selected':''}>Email</option><option value="whatsapp" ${t.channel==='whatsapp'?'selected':''}>WhatsApp</option><option value="sms" ${t.channel==='sms'?'selected':''}>SMS</option><option value="note" ${t.channel==='note'?'selected':''}>Note</option></select></div><div class="form-group"><label>Subject</label><input class="fi" id="tpl-subject" value="${t.subject||''}"/></div><div class="form-group"><label>Body</label><textarea class="fi ta" id="tpl-body" rows="5">${t.body}</textarea></div>`,[{label:'Update',cls:'btn-primary',action:async()=>{const data={name:document.getElementById('tpl-name').value.trim(),channel:document.getElementById('tpl-channel').value,subject:document.getElementById('tpl-subject').value.trim(),body:document.getElementById('tpl-body').value.trim()};await api(`/api/templates/${id}`,{method:'PUT',body:JSON.stringify(data)});toast('Updated!');closeModal();const tr=await api('/api/templates');if(tr)templates=await tr.json();renderTemplates();}}]);}
async function deleteTemplate(id){if(!confirm('Delete?'))return;await api(`/api/templates/${id}`,{method:'DELETE'});toast('Deleted');const tr=await api('/api/templates');if(tr)templates=await tr.json();renderTemplates();}

// REMINDERS
function renderReminders(){
  document.getElementById('remindersBody').innerHTML=[...reminders].sort((a,b)=>new Date(a.due_at)-new Date(b.due_at)).map(r=>{const isPast=r.status==='pending'&&new Date(r.due_at)<new Date();return`<tr><td style="font-weight:500">${r.contact_name||'—'}</td><td><span class="status-badge badge-${r.channel}">${r.channel}</span></td><td style="font-size:12px;color:var(--text-secondary);max-width:200px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap">${r.message}</td><td style="color:${isPast?'var(--accent-red)':'var(--text-secondary)'}">${$d(r.due_at)}</td><td><span class="status-badge ${r.status==='done'?'badge-Client':isPast?'badge-Churned':'badge-Lead'}">${r.status==='done'?'done':isPast?'overdue':'pending'}</span></td><td><div class="actions-cell">${r.status!=='done'?`<button class="icon-btn" title="Done" onclick="doneReminder(${r.id})"><svg viewBox="0 0 16 16" fill="none" stroke="currentColor" stroke-width="1.5"><polyline points="2,8 6,12 14,4"/></svg></button>`:''}<button class="icon-btn del" onclick="deleteReminder(${r.id})"><svg viewBox="0 0 16 16" fill="none" stroke="currentColor" stroke-width="1.5"><path d="M2 4h12M5 4V2h6v2M6 7v5M10 7v5M3 4l1 10h8l1-10"/></svg></button></div></td></tr>`}).join('')||'<tr><td colspan="6" style="padding:40px;text-align:center;color:var(--text-muted)">No reminders set</td></tr>';
}
document.getElementById('addReminderBtn')?.addEventListener('click',()=>{const cOpts=contacts.map(c=>`<option value="${c.id}">${c.name} — ${c.company||'—'}</option>`).join('');openModal('Set Reminder',`<div class="form-group"><label>Contact</label><select class="fi" id="rem-contact"><option value="">Select…</option>${cOpts}</select></div><div class="form-group"><label>Channel</label><select class="fi" id="rem-channel"><option value="email">Email</option><option value="whatsapp">WhatsApp</option><option value="sms">SMS</option></select></div><div class="form-group"><label>Message</label><textarea class="fi ta" id="rem-msg" rows="3" placeholder="Hi {{name}}, just checking in…"></textarea></div><div class="form-group"><label>Send At</label><input type="datetime-local" class="fi" id="rem-due"/></div><div class="form-group"><label>Repeat every N days (optional)</label><input type="number" class="fi" id="rem-repeat" placeholder="e.g. 7"/></div>`,[{label:'Set Reminder',cls:'btn-primary',action:async()=>{const data={contact_id:parseInt(document.getElementById('rem-contact').value),channel:document.getElementById('rem-channel').value,message:document.getElementById('rem-msg').value.trim(),due_at:new Date(document.getElementById('rem-due').value).toISOString(),repeat_days:parseInt(document.getElementById('rem-repeat').value)||null};if(!data.contact_id||!data.message){toast('Contact and message required','warn');return}await api('/api/reminders',{method:'POST',body:JSON.stringify(data)});toast('Reminder set!');closeModal();const rr=await api('/api/reminders');if(rr)reminders=await rr.json();renderReminders();}}]);});
async function doneReminder(id){await api(`/api/reminders/${id}/done`,{method:'PATCH'});toast('Done!');const rr=await api('/api/reminders');if(rr)reminders=await rr.json();renderReminders();}
async function deleteReminder(id){if(!confirm('Delete?'))return;await api(`/api/reminders/${id}`,{method:'DELETE'});toast('Deleted');const rr=await api('/api/reminders');if(rr)reminders=await rr.json();renderReminders();}

// ANALYTICS
async function renderAnalytics(){
  const total=contacts.length||1;const statuses=['Lead','Client','Partner','Churned'];
  const sCols={Lead:'var(--accent-amber)',Client:'var(--accent-green)',Partner:'var(--accent-blue)',Churned:'var(--accent-red)'};
  const byCnt=Object.fromEntries(statuses.map(s=>[s,contacts.filter(c=>c.status===s).length]));
  const pipeline=contacts.reduce((s,c)=>s+(Number(c.deal)||0),0);
  const revenue=invoices.filter(i=>i.status==='paid').reduce((s,i)=>s+(Number(i.total)||0),0);
  const topDeals=[...contacts].filter(c=>c.deal>0).sort((a,b)=>b.deal-a.deal).slice(0,5);
  const fr=await api('/api/ai/forecast');const forecast=fr?await fr.json():null;
  document.getElementById('analyticsGrid').innerHTML=`
    <div class="analytics-panel"><div class="ap-title">Status Distribution</div>${statuses.map(s=>{const pct=Math.round(byCnt[s]/total*100);return`<div class="bar-row"><span class="bar-label">${s}</span><div class="bar-track" style="flex:1"><div class="bar-fill" style="width:${pct}%;background:${sCols[s]}"></div></div><span class="bar-val">${byCnt[s]}</span></div>`}).join('')}</div>
    <div class="analytics-panel"><div class="ap-title">Key Metrics</div><div style="display:grid;grid-template-columns:1fr 1fr;gap:8px">${[{label:'Contacts',val:contacts.length},{label:'Pipeline',val:$m(pipeline)},{label:'Revenue',val:$m(revenue)},{label:'Proposals',val:proposals.length},{label:'Projects',val:projects.length},{label:'Open Tickets',val:tickets.filter(t=>t.status==='open').length}].map(m=>`<div style="background:var(--bg-elevated);border-radius:var(--radius-md);padding:10px 12px"><div style="font-size:10px;text-transform:uppercase;letter-spacing:.08em;color:var(--text-muted);margin-bottom:4px">${m.label}</div><div style="font-family:var(--font-serif);font-size:20px">${m.val}</div></div>`).join('')}</div></div>
    <div class="analytics-panel"><div class="ap-title">Top Deals</div>${topDeals.map((c,i)=>`<div class="deal-row"><span class="deal-rank">${i+1}</span><div><div class="deal-name">${c.name}</div><div class="deal-company">${c.company||'—'}</div></div><div class="deal-amount">${$m(c.deal)}</div></div>`).join('')||'<p style="color:var(--text-muted);font-size:13px">No deals yet</p>'}</div>
    ${forecast?`<div class="analytics-panel"><div class="ap-title">Churn Risk</div>${(forecast.churn_risk||[]).slice(0,5).map(c=>`<div class="deal-row"><div><div class="deal-name">${c.name}</div><div class="deal-company">${c.days_since_contact}d since contact</div></div><span class="status-badge ${c.risk_level==='high'?'badge-Churned':c.risk_level==='medium'?'badge-Lead':'badge-Client'}">${c.risk_level}</span></div>`).join('')||'<p style="color:var(--accent-green);font-size:13px">No churn risk detected ✅</p>'}</div>`:''}`;
}

// TEAM
async function renderTeam(){const res=await api('/api/team');if(!res)return;const team=await res.json();document.getElementById('teamGrid').innerHTML=team.map((u,i)=>{const av=pal(u.user_name);return`<div class="team-card"><div class="team-card-header"><div style="width:38px;height:38px;border-radius:50%;background:${av.bg};color:${av.c};font-size:13px;font-weight:600;display:flex;align-items:center;justify-content:center">${init(u.user_name)}</div><div><div style="font-weight:500">${u.user_name}</div><div style="font-size:11px;color:var(--text-muted)">${u.role} · ${$ago(u.last_login)}</div></div>${i===0?'<span style="margin-left:auto;font-size:20px">🏆</span>':''}</div><div class="team-stats-grid"><div class="team-stat"><div class="ts-val">${u.contacts_added||0}</div><div class="ts-label">Contacts</div></div><div class="team-stat"><div class="ts-val">${u.messages_sent||0}</div><div class="ts-label">Messages</div></div><div class="team-stat"><div class="ts-val">${u.deals_closed||0}</div><div class="ts-label">Deals</div></div><div class="team-stat"><div class="ts-val" style="color:var(--accent-green)">${$m(u.revenue||0)}</div><div class="ts-label">Revenue</div></div></div></div>`}).join('')||'<div style="color:var(--text-muted);font-size:13px">No team data</div>';}

// BILLING
async function renderBilling(){const res=await api('/api/billing/plans');if(!res)return;const plans=await res.json();const current=TENANT.plan||'starter';document.getElementById('billingSubtitle').textContent=`Current: ${current} · ${TENANT.sub_status||'active'}`;document.getElementById('plansGrid').innerHTML=plans.map(p=>`<div class="plan-card ${p.id==='pro'?'popular':''}">${p.id==='pro'?'<div class="popular-tag">Most Popular</div>':''}<div class="plan-name">${p.name}</div><div class="plan-price">$${p.price}<span>/mo</span></div><ul class="plan-features">${p.features.map(f=>`<li>${f}</li>`).join('')}</ul><button class="plan-btn ${p.id===current?'current':p.id==='pro'?'primary':''}" onclick="selectPlan('${p.id}')" ${p.id===current?'disabled':''}>${p.id===current?'✓ Current Plan':`Upgrade to ${p.name}`}</button></div>`).join('');const wr=await api('/api/webhooks');const webhooks=wr?await wr.json():[];document.getElementById('webhookList').innerHTML=webhooks.length?webhooks.map(w=>`<div class="webhook-row"><span class="webhook-events">${w.events}</span><span class="webhook-url">${w.url}</span><button class="icon-btn del" onclick="delWebhook(${w.id})"><svg viewBox="0 0 16 16" fill="none" stroke="currentColor" stroke-width="1.5"><line x1="3" y1="3" x2="13" y2="13"/><line x1="13" y1="3" x2="3" y2="13"/></svg></button></div>`).join(''):'<div style="padding:16px 18px;font-size:13px;color:var(--text-muted)">No webhooks configured.</div>';}
function selectPlan(plan){openModal(`Upgrade to ${plan}`,`<p style="font-size:13px;color:var(--text-secondary);line-height:1.7">Set <code>STRIPE_SECRET_KEY</code> and Price IDs in your <code>.env</code> file to activate Stripe payments.</p>`,[{label:'Confirm',cls:'btn-primary',action:async()=>{const res=await api('/api/billing/checkout',{method:'POST',body:JSON.stringify({plan})});const d=res?await res.json():{};toast(d.error||'Configure Stripe in .env first','warn');closeModal();}}]);}
document.getElementById('stripePortalBtn')?.addEventListener('click',async()=>{const res=await api('/api/billing/portal');const d=res?await res.json():{};if(d.url)window.open(d.url,'_blank');else toast(d.error||'Stripe not configured','warn');});
document.getElementById('addWebhookBtn')?.addEventListener('click',()=>{const evts=['contact.created','contact.updated','contact.deleted','invoice.paid','invoice.sent','message.sent','proposal.accepted'];openModal('Add Zapier Webhook',`<div class="form-group"><label>Webhook URL</label><input class="fi" id="wh-url" placeholder="https://hooks.zapier.com/…"/></div><div class="form-group"><label>Events</label>${evts.map(e=>`<label style="display:flex;align-items:center;gap:7px;font-size:13px;margin-bottom:5px;color:var(--text-secondary)"><input type="checkbox" value="${e}" class="wh-ev"/> ${e}</label>`).join('')}</div>`,[{label:'Save',cls:'btn-primary',action:async()=>{const url=document.getElementById('wh-url').value.trim();const events=[...document.querySelectorAll('.wh-ev:checked')].map(e=>e.value);if(!url||!events.length){toast('URL and events required','warn');return}const res=await api('/api/webhooks',{method:'POST',body:JSON.stringify({url,events})});const d=res?await res.json():{};toast(`Webhook saved! Secret: ${d.secret}`);closeModal();renderBilling();}}]);});
async function delWebhook(id){await api(`/api/webhooks/${id}`,{method:'DELETE'});toast('Deleted');renderBilling();}

// ADMIN
async function renderAdmin(){if(CUSER.role!=='admin')return;const[ur,ir]=await Promise.all([api('/api/users'),api('/api/integrations')]);const users=ur?await ur.json():[];const integs=ir?await ir.json():[];const connected=new Set(integs.filter(i=>i.enabled).map(i=>i.type));document.getElementById('userBody').innerHTML=users.map(u=>`<tr><td style="font-weight:500">${u.name}</td><td style="color:var(--text-secondary)">${u.email}</td><td><span class="role-chip role-${u.role}">${u.role}</span></td><td style="color:var(--text-muted)">${$ago(u.last_login)}</td><td>${u.id!==CUSER.id?`<button class="icon-btn del" onclick="deleteUser(${u.id})"><svg viewBox="0 0 16 16" fill="none" stroke="currentColor" stroke-width="1.5"><path d="M2 4h12M5 4V2h6v2M6 7v5M10 7v5M3 4l1 10h8l1-10"/></svg></button>`:'<span style="font-size:11px;color:var(--text-muted)">You</span>'}</td></tr>`).join('');const IMETA={google_calendar:{icon:'📅',name:'Google Calendar'},twilio:{icon:'📱',name:'Twilio SMS'},slack:{icon:'💬',name:'Slack'},zapier:{icon:'⚡',name:'Zapier'},stripe:{icon:'💳',name:'Stripe'}};document.getElementById('integrationList').innerHTML=Object.entries(IMETA).map(([type,m])=>`<div class="integration-row"><div class="integ-icon">${m.icon}</div><div><div class="integ-name">${m.name}</div><div class="integ-status">${connected.has(type)?'Connected':'Not connected'}</div></div><div class="toggle-wrap"><label class="toggle"><input type="checkbox" ${connected.has(type)?'checked':''} onchange="toggleInteg('${type}',this.checked)"/><span class="toggle-slider"></span></label></div></div>`).join('');const br=await api('/api/branding');const branding=br?await br.json():{};const bf=document.getElementById('brandingForm');if(bf)bf.innerHTML=`<div class="form-group"><label>App Name</label><input class="fi" id="brand-name" value="${branding.app_name||'NexusCRM'}"/></div><div class="form-group"><label>Tagline</label><input class="fi" id="brand-tagline" value="${branding.tagline||''}"/></div><div class="form-group"><label>Primary Color</label><input type="color" class="fi" id="brand-color" value="${branding.primary_color||'#3b82f6'}" style="height:36px;padding:4px"/></div><button class="btn-primary" style="margin-top:4px" onclick="saveBranding()">Save Branding</button>`;const pi=document.getElementById('portalInviteWrap');if(pi){const cOpts=contacts.map(c=>`<option value="${c.id}">${c.name} — ${c.email||'no email'}</option>`).join('');pi.innerHTML=`<select class="fi" id="portalContact" style="margin-bottom:8px"><option value="">Select contact…</option>${cOpts}</select><button class="btn-ghost" onclick="sendPortalInvite()">Send Portal Invite</button>`;}}
document.getElementById('addUserBtn')?.addEventListener('click',()=>{openModal('Add Team Member',`<div class="form-group"><label>Full Name</label><input class="fi" id="nu-name" placeholder="Jane Smith"/></div><div class="form-group"><label>Email</label><input class="fi" id="nu-email" type="email" placeholder="jane@company.com"/></div><div class="form-group"><label>Password</label><input class="fi" id="nu-pass" type="password" placeholder="Min 6 characters"/></div><div class="form-group"><label>Role</label><select class="fi" id="nu-role"><option value="user">User</option><option value="admin">Admin</option></select></div>`,[{label:'Create User',cls:'btn-primary',action:async()=>{const data={name:document.getElementById('nu-name').value.trim(),email:document.getElementById('nu-email').value.trim(),password:document.getElementById('nu-pass').value,role:document.getElementById('nu-role').value};if(!data.name||!data.email||!data.password){toast('All fields required','warn');return}const res=await api('/api/auth/register',{method:'POST',body:JSON.stringify(data)});const d=res?await res.json():{};if(d.error){toast(d.error,'error');return}toast(`User ${data.name} created!`);closeModal();renderAdmin();}}]);});
async function deleteUser(id){if(!confirm('Delete user?'))return;await api(`/api/users/${id}`,{method:'DELETE'});toast('Deleted');renderAdmin();}
async function toggleInteg(type,enabled){await api(`/api/integrations/${type}/toggle`,{method:'PATCH',body:JSON.stringify({enabled})});toast(`${type} ${enabled?'enabled':'disabled'}`)}
async function saveBranding(){const data={app_name:document.getElementById('brand-name').value,tagline:document.getElementById('brand-tagline').value,primary_color:document.getElementById('brand-color').value};await api('/api/branding',{method:'PUT',body:JSON.stringify(data)});toast('Branding saved!');}
async function sendPortalInvite(){const cid=parseInt(document.getElementById('portalContact').value);if(!cid){toast('Select a contact','warn');return}const res=await api(`/api/portal/invite/${cid}`,{method:'POST'});if(!res)return;const d=await res.json();if(d.portalUrl){toast(d.message||'Invite sent!');openModal('Portal Link',`<p style="font-size:13px;color:var(--text-secondary);margin-bottom:10px">${d.message}</p><div style="background:var(--bg-elevated);border-radius:8px;padding:12px;font-size:12px;font-family:monospace;word-break:break-all;color:var(--accent-blue)">${d.portalUrl}</div>`,[])}else toast(d.error,'error');}

// SLIDE-OVER
function openPanel(){document.getElementById('overlay').classList.add('open');document.getElementById('slideover').classList.add('open')}
function closePanel(){document.getElementById('overlay').classList.remove('open');document.getElementById('slideover').classList.remove('open');editingId=null;isAdding=false;}
document.getElementById('overlay')?.addEventListener('click',closePanel);
document.getElementById('soClose')?.addEventListener('click',closePanel);
function setSOAv(name){setAv(document.getElementById('soAvatar'),name||'NC')}

function openView(id){
  const c=contacts.find(x=>x.id===id);if(!c)return;
  editingId=null;isAdding=false;setSOAv(c.name);
  document.getElementById('soName').textContent=c.name;
  document.getElementById('soRole').textContent=`${c.title||'—'} · ${c.company||'—'}`;
  const score=c.deal_score??0;
  document.getElementById('soBody').innerHTML=`<div style="display:flex;align-items:center;gap:8px;padding:8px 0;border-bottom:1px solid var(--border);margin-bottom:4px"><div style="flex:1;height:5px;background:var(--bg-elevated);border-radius:99px;overflow:hidden"><div style="width:${score}%;height:100%;background:${scoreColor(score)};border-radius:99px;transition:width .5s"></div></div><span style="font-size:12px;font-weight:600;color:${scoreColor(score)}">${score}%</span></div><div class="field-row"><span class="f-label">Email</span><span class="f-val" style="color:var(--accent-blue)">${c.email||'—'}</span></div><div class="field-row"><span class="f-label">Phone</span><span class="f-val">${c.phone||'—'}</span></div><div class="field-row"><span class="f-label">WhatsApp</span><span class="f-val">${c.whatsapp||c.phone||'—'}</span></div><div class="field-row"><span class="f-label">Company</span><span class="f-val">${c.company||'—'}</span></div><div class="field-row"><span class="f-label">Status</span><span class="f-val"><span class="status-badge badge-${c.status}">${c.status}</span></span></div><div class="field-row"><span class="f-label">Stage</span><span class="f-val">${c.stage||'—'}</span></div><div class="field-row"><span class="f-label">Deal</span><span class="f-val" style="font-weight:600;color:var(--accent-green)">${$m(c.deal)}</span></div><div class="field-row"><span class="f-label">Last Contact</span><span class="f-val">${$d(c.last_contact)}</span></div><div class="notes-section"><div class="notes-label">Notes</div><div class="notes-text">${c.notes||'No notes yet.'}</div></div>`;
  document.getElementById('soFooter').innerHTML=`<button class="btn-save" onclick="openEdit(${c.id})">Edit</button><button class="btn-ghost" style="color:#25d366;border-color:rgba(37,211,102,.3)" onclick="quickWA(${c.id})">WhatsApp</button><button class="btn-cancel" onclick="closePanel()">Close</button>`;
  openPanel();
}

function openEdit(id){const c=contacts.find(x=>x.id===id);if(!c)return;editingId=id;isAdding=false;setSOAv(c.name);document.getElementById('soName').textContent='Edit Contact';document.getElementById('soRole').textContent=c.company||'';renderForm(c);openPanel();}
function openAdd(){isAdding=true;editingId=null;setSOAv('NC');document.getElementById('soName').textContent='New Contact';document.getElementById('soRole').textContent='Fill in the details below';renderForm({name:'',email:'',phone:'',whatsapp:'',company:'',title:'',status:'Lead',stage:'Lead',deal:'',last_contact:'',notes:''});openPanel();}
function renderForm(c){
  const selStatus=['Lead','Client','Partner','Churned'].map(s=>`<option ${c.status===s?'selected':''}>${s}</option>`).join('');
  const selStage=['Lead','Qualified','Proposal','Closed'].map(s=>`<option ${(c.stage||'Lead')===s?'selected':''}>${s}</option>`).join('');
  document.getElementById('soBody').innerHTML=`<div class="field-row"><span class="f-label">Name</span><input class="fi" id="f-name" value="${c.name||''}" placeholder="Full name" oninput="liveAv()"/></div><div class="field-row"><span class="f-label">Email</span><input class="fi" id="f-email" type="email" value="${c.email||''}" placeholder="email@company.com"/></div><div class="field-row"><span class="f-label">Phone</span><input class="fi" id="f-phone" value="${c.phone||''}" placeholder="+1 000 000 0000"/></div><div class="field-row"><span class="f-label">WhatsApp</span><input class="fi" id="f-wa" value="${c.whatsapp||''}" placeholder="Same as phone?"/></div><div class="field-row"><span class="f-label">Company</span><input class="fi" id="f-company" value="${c.company||''}" placeholder="Company name"/></div><div class="field-row"><span class="f-label">Title</span><input class="fi" id="f-title" value="${c.title||''}" placeholder="Job title"/></div><div class="field-row"><span class="f-label">Status</span><select class="fi" id="f-status">${selStatus}</select></div><div class="field-row"><span class="f-label">Stage</span><select class="fi" id="f-stage">${selStage}</select></div><div class="field-row"><span class="f-label">Deal ($)</span><input class="fi" id="f-deal" type="number" value="${c.deal||''}" placeholder="0"/></div><div class="field-row"><span class="f-label">Last Contact</span><input class="fi" id="f-date" type="date" value="${c.last_contact||''}"/></div><div class="notes-section"><div class="notes-label">Notes</div><textarea class="fi ta" id="f-notes" placeholder="Notes…">${c.notes||''}</textarea></div>`;
  document.getElementById('soFooter').innerHTML=`<button class="btn-save" onclick="handleSave()">Save</button><button class="btn-cancel" onclick="${editingId?`openView(${editingId})`:'closePanel()'}">Cancel</button>`;
}
function liveAv(){const name=document.getElementById('f-name').value;setSOAv(name||'NC');document.getElementById('soName').textContent=name||'New Contact';}
async function handleSave(){
  const get=id=>document.getElementById(id)?.value||'';
  const data={name:get('f-name').trim(),email:get('f-email').trim(),phone:get('f-phone').trim(),whatsapp:get('f-wa').trim(),company:get('f-company').trim(),title:get('f-title').trim(),status:get('f-status'),stage:get('f-stage'),deal:parseFloat(get('f-deal'))||0,last_contact:get('f-date'),notes:get('f-notes').trim()};
  if(!data.name){toast('Name required','warn');return}
  let res;
  if(isAdding)res=await api('/api/contacts',{method:'POST',body:JSON.stringify(data)});
  else res=await api(`/api/contacts/${editingId}`,{method:'PUT',body:JSON.stringify(data)});
  if(!res?.ok){toast('Failed to save','error');return}
  const saved=await res.json();
  if(isAdding){contacts.push(saved)}else{const idx=contacts.findIndex(c=>c.id===saved.id);if(idx!==-1)contacts[idx]=saved;}
  document.getElementById('navContactCount').textContent=contacts.length;
  renderContacts();toast(`Contact ${isAdding?'created':'updated'}!`);
  if(isAdding)closePanel();else openView(editingId);
}
async function handleDelete(id){const c=contacts.find(x=>x.id===id);if(!c)return;if(!confirm(`Delete ${c.name}?`))return;await api(`/api/contacts/${id}`,{method:'DELETE'});contacts=contacts.filter(x=>x.id!==id);document.getElementById('navContactCount').textContent=contacts.length;closePanel();renderContacts();toast('Deleted');}

function exportCSV(){const hdrs=['Name','Email','Phone','WhatsApp','Company','Title','Status','Stage','Deal','Score','Last Contact','Notes'];const rows=contacts.map(c=>[c.name,c.email,c.phone,c.whatsapp,c.company,c.title,c.status,c.stage,c.deal,c.deal_score,c.last_contact,c.notes].map(v=>`"${(v||'').toString().replace(/"/g,'""')}"`).join(','));const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([[hdrs.join(','),...rows].join('\n')],{type:'text/csv'}));a.download='nexuscrm-contacts.csv';a.click();toast('Exported!');}

function openModal(title,bodyHtml,actions=[]){document.getElementById('modalTitle').textContent=title;document.getElementById('modalBody').innerHTML=bodyHtml;document.getElementById('modalFooter').innerHTML=[...actions.map(a=>`<button class="${a.cls||'btn-ghost'}" id="ma_${a.label.replace(/\s/g,'_')}">${a.label}</button>`),`<button class="btn-cancel" onclick="closeModal()">Cancel</button>`].join('');actions.forEach(a=>document.getElementById(`ma_${a.label.replace(/\s/g,'_')}`)?.addEventListener('click',a.action));document.getElementById('modalOverlay').style.display='flex';}
function closeModal(){document.getElementById('modalOverlay').style.display='none';invItems=[];propItems=[];}
document.getElementById('modalClose')?.addEventListener('click',closeModal);
document.getElementById('modalOverlay')?.addEventListener('click',e=>{if(e.target===e.currentTarget)closeModal();});

// BOOT
(async()=>{initSidebar();await loadAll();navigateTo('dashboard');})();
